default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('DODownloadMode', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]$ODV_do_download_mode)) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization [DODownloadMode]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

---

{{ if .Vars.win11cis_level_1 }}
  {{ if .Vars.win11cis_rule_18_10_16_1 }}
registry:
  HKLM\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization\DODownloadMode:
    title: "18.10.16.1 | Ensure 'Download Mode' is NOT set to 'Enabled: Internet' | DODownloadMode"
    exists: true
    value: {{ .Vars.win11cis_do_download_mode }}
    type: REG_DWORD
    meta:
      workstation: 1
      CIS_ID:
        - 18.10.16.1
  {{ end }}
{{ end }}

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization')) {
    New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization' -Name 'DODownloadMode' -Value $ODV_do_download_mode -PropertyType DWord -Force | Out-Null
exit 0
